const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    terminal: false
});

let lines = [];
let lineIndex = 0;

function scanf() {
    if (lineIndex >= lines.length) {
        return null;
    }
    const line = lines[lineIndex++];
    return line.trim().split(/\s+/).map(Number);
}

function main() {
    let pending = new Promise((resolve, reject) => {
        rl.on('line', (line) => {
            lines.push(line);
        });
        rl.on('close', () => {
            resolve();
        });
    });

    pending.then(() => {
        const t = scanf()[0];
        const results = [];

        for (let i = 0; i < t; i++) {
            const [n, k] = scanf();
            const mod = 1000000007n;
            const base = BigInt(n);
            const exp = BigInt(k);

            let result = 1n;
            let b = base % mod;
            let e = exp;

            while (e > 0n) {
                if (e % 2n === 1n) {
                    result = (result * b) % mod;
                }
                b = (b * b) % mod;
                e = e / 2n;
            }

            results.push(result.toString());
        }

        process.stdout.write(results.join('\n') + '\n');
    });
}

main();
